    center: P(0, 0.735, 0.335),
    size: [0.15, 0.13, 0.07],
    slot: SLOT.metal,
    weights: wTorso,
    color: V(1.15),
  });

  // Loincloth, front and back.
  for (const s of [1, -1]) {
    plate(B, {
      corners: [
        P(-0.13, 0.72, 0.3 * s),
        P(0.13, 0.72, 0.3 * s),
        P(0.11, 0.38, 0.26 * s),
        P(-0.11, 0.38, 0.26 * s),
