  // Eyes: a dark socket with a hot pinprick inside.
  for (const s of [1, -1]) {
    blob(B, {
      center: P(0.078 * s, hy + 0.015, 0.155),
      radius: [0.05, 0.045, 0.035],
      segU: 7,
      segV: 5,
      slot: SLOT.none,
      weights: wHead,
      color: () => SOCKET,
    });
    blob(B, {
      center: P(0.082 * s, hy + 0.018, 0.182),
      radius: [0.028, 0.03, 0.02],
      segU: 6,
      segV: 4,
      slot: SLOT.glowA,
      weights: wHead,
      color: () => V(1.3),
    });
  }

  // Snout ridge + nostrils.
  boxFlat(B, {
    center: P(0, hy - 0.045, 0.215),
    size: [0.11, 0.07, 0.09],
    slot: SLOT.skin,
    weights: wHead,
    color: V(1.12),
