constructor(ctx) {
    this.ctx = ctx;
    this.group = new THREE.Group();
    this.group.name = 'fx';
    this.group.matrixAutoUpdate = false;

    // Read by CameraRig every frame — must exist before build().
    this.shake = { amount: 0, time: 0 };

    this.time = 0;
    this.enabled = true;

    const q = ctx?.engine?.qualityName ?? 'high';
    this.budget = QUALITY_BUDGET[q] ?? 1;

    // Deterministic per-seed stream, then a cheap local PRNG for the millions
    // of per-particle jitters that must not perturb world generation.
    const fork = ctx?.rng?.fork ? ctx.rng.fork('fx') : null;
    const s = fork ? (fork.int ? fork.int(1, 0x7ffffffe) : 12345) : 0x9e3779b9;
    this.rnd = mulberry32(s >>> 0);

    this.p = makeEmitParams();

    this._flame = { on: false, frac: 0, ring: 0, smoke: 0, light: 0, scorch: 0 };
    this._charge = { on: false, frac: 0, scuff: 0 };
    this._glide = { on: false, frac: 0 };
    this._trails = [];
    this._updrafts = [];
    this._handlers = [];
    this._origin = new THREE.Vector3();
    this._dir = new THREE.Vector3(0, 0, 1);
    this._fogColor = new THREE.Color(0xa9d4f2);
    this._registeredUpdrafts = false;
  }

